/**
 * Fetch tickets from backend PostgreSQL sales API.
 */
const fetchKitchenTickets = async () => {
  try {
    const response = await fetch('/api/sales');
    if (response.ok) {
      const sales = await response.json();
      return (sales || []).map((s) => ({
        id: 'SALE-' + s.id,
        orderNumber: '#' + s.id,
        table: s.paymentMethod ? s.paymentMethod : 'POS',
        server: s.customer ? (s.customer.name || 'Customer #' + s.customer.id) : 'Walk-in',
        createdAt: s.createdAt || new Date().toISOString(),
        status: (s.status || 'PENDING').toUpperCase(),
        orderType: s.paymentMethod === 'DELIVERY' ? 'Delivery' : 'Dine-in',
        station: 'kitchen',
        specialInstructions: s.region ? ('Region: ' + s.region) : '',
        items: (s.items || []).map((i) => ({
          name: i.product ? i.product.name : ('Item #' + (i.id || '')),
          qty: i.quantity || 1,
          modifiers: [],
          done: false
        }))
      }));
    }
  } catch (e) {
    console.warn('Could not fetch sales from backend:', e);
  }
  return [];
};

